def encode(message):
    result = []
    vowels = 'aeiou'
    for char in message:
        if char.isalpha():
            # Swap case
            if char.islower():
                char = char.upper()
            else:
                char = char.lower()
            # Replace vowels with letter 2 places ahead
            if char in vowels:
                # Find the index of the vowel
                idx = vowels.index(char)
                # Calculate new index
                new_idx = (idx + 2) % 5
                char = vowels[new_idx]
        result.append(char)
    return ''.join(result)

